// Coverage index (generated by scripts/build-cpts.mjs). Without scripts the page
// is the whole list: every map, phase, node and reference table, each a link.
// This adds the page chrome (Ctrl+K, header, theme, hero) and a live search that
// filters across every entry and rolls the visibility up to phases and maps.
import { initCommandPalette } from "../../js/command-palette.js?v=search2";
import { initSiteHeader } from "../../js/site-header.js?v=276fa973-header";
import { initTheme } from "../../js/theme.js?v=276fa973";
import { initHeroDither } from "../../js/hero-dither.js?v=276fa973-idle";

const initSearch = () => {
  const input = document.getElementById("cov-q");
  if (!input) return;
  const count = document.getElementById("cov-count");
  const empty = document.getElementById("cov-empty");
  const nodes = [...document.querySelectorAll(".cov-node")];
  const phases = [...document.querySelectorAll(".cov-phase")];
  const maps = [...document.querySelectorAll(".cov-map")];
  const total = count ? count.textContent : "";

  const apply = () => {
    const q = input.value.trim().toLowerCase();
    let shown = 0;
    for (const node of nodes) {
      const match = !q || (node.dataset.search || "").includes(q);
      node.hidden = !match;
      if (match) shown += 1;
    }
    for (const phase of phases) {
      const phaseMatch = !q || (phase.dataset.search || "").includes(q);
      const phaseNodes = [...phase.querySelectorAll(".cov-node")];
      const anyNode = phaseNodes.some((n) => !n.hidden);
      // A phase whose own name matches shows all its nodes, even if none matched.
      if (q && phaseMatch && !anyNode) {
        for (const n of phaseNodes) { n.hidden = false; shown += 1; }
      }
      phase.hidden = !(phaseMatch || anyNode);
    }
    for (const map of maps) {
      const anyPhase = [...map.querySelectorAll(".cov-phase")].some((p) => !p.hidden);
      map.hidden = !anyPhase;
    }
    if (count) count.textContent = q ? `${shown} match${shown === 1 ? "" : "es"}` : total;
    if (empty) empty.hidden = shown > 0 || !q;
  };

  input.addEventListener("input", apply);
  apply();
};

document.addEventListener("DOMContentLoaded", () => {
  initCommandPalette();
  initSiteHeader();
  initTheme();
  initHeroDither();
  initSearch();
});
